/*
    Insert serial numbers from gmpreprod_v2.txt into PWInventory.dbo.Item.

    HOW TO RUN IN DBEAVER:
      1. Open this file in a SQL editor connected to the preprod SQL Server.
      2. Select ALL text (Ctrl+A) and press Ctrl+Enter (Execute SQL statement).
         Do not use Alt+X (Execute Script): DBeaver would send each statement
         separately and the @variables would be lost between them.
    The whole script is one BEGIN...END block and uses three-part names, so no
    USE / GO is needed.

    - One row per distinct, non-empty serial in the file (file duplicates are collapsed).
    - Serials already present for the entity are skipped (unique key IX_Item_Entity_Serial),
      so the script is safe to rerun.
    - Part is derived from characters 15-22 of the serial (85545338 = Left, 85545339 = Right)
      and looked up in dbo.Part for the entity. The script aborts before inserting if any
      part is missing.
    - Items are born Serialized, default status, quantity 1, Birth_DateTime = now,
      matching what ActionBirth does in the PlantWatch logic.
    - All rows are written by a single INSERT, so the write is atomic.
*/
BEGIN
SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @EntityName varchar(100) = 'Angstrom';   -- producer used by ActionBirth
DECLARE @Entity_Key int = (SELECT Entity_Key      FROM PWInventory.dbo.Entity      WHERE Entity = @EntityName);
DECLARE @Type_Key   int = (SELECT Item_Type_Key   FROM PWInventory.dbo.Item_Type   WHERE Item_Type_Name = 'Serialized');
DECLARE @Status_Key int = (SELECT Item_Status_Key FROM PWInventory.dbo.Item_Status WHERE Default_Status = 1);
IF @Entity_Key IS NULL THROW 50000, 'Entity not found in dbo.Entity; set @EntityName.', 1;
IF @Type_Key   IS NULL THROW 50000, 'Item type ''Serialized'' not found in dbo.Item_Type.', 1;
IF @Status_Key IS NULL THROW 50000, 'No default status found in dbo.Item_Status.', 1;
CREATE TABLE #Serials (Serial_Nbr varchar(100) NOT NULL PRIMARY KEY);
INSERT INTO #Serials (Serial_Nbr)
SELECT DISTINCT v.Serial_Nbr
FROM (VALUES
