-- Resolve each serial to its part.
SELECT  s.Serial_Nbr,
        SUBSTRING(s.Serial_Nbr, 15, 8) AS Part_Number,
        p.Part_Key
INTO    #Resolved
FROM    #Serials s
LEFT JOIN PWInventory.dbo.Part p
       ON p.Part_Number = SUBSTRING(s.Serial_Nbr, 15, 8)
      AND p.Entity_Key  = @Entity_Key;
IF EXISTS (SELECT 1 FROM #Resolved WHERE Part_Key IS NULL)
BEGIN
    SELECT DISTINCT Part_Number AS MissingPartNumber FROM #Resolved WHERE Part_Key IS NULL;
    THROW 50000, 'One or more part numbers derived from the serials do not exist in dbo.Part for this entity. Nothing inserted.', 1;
END;
INSERT INTO PWInventory.dbo.Item (Entity_Key, Serial_Nbr, Part_Key, Type_Key, Current_RouteOp_Key, Status_Key, Birth_DateTime, Birth_RouteOp_Key, LotQuantity)
SELECT  @Entity_Key, r.Serial_Nbr, r.Part_Key, @Type_Key, NULL, @Status_Key, GETDATE(), NULL, 1
FROM    #Resolved r
WHERE   NOT EXISTS (SELECT 1 FROM PWInventory.dbo.Item i
                    WHERE i.Entity_Key = @Entity_Key
                      AND i.Serial_Nbr = r.Serial_Nbr);
DECLARE @Inserted int = @@ROWCOUNT;
DECLARE @Total    int = (SELECT COUNT(*) FROM #Serials);
-- Result row shown in the grid (DBeaver may not display PRINT output).
SELECT  @Total AS SerialsInFile, @Inserted AS Inserted, @Total - @Inserted AS AlreadyPresentSkipped;
DROP TABLE #Resolved;
DROP TABLE #Serials;
END
